import json
with open('baseline-packages.json') as f: data = json.load(f)
with open('after-cpm-packages.json') as g: after = json.load(g)

def extract(d):
    result = {}
    for proj in d.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                result.setdefault(name, {})[pkg['id']] = pkg.get('resolvedVersion','')
    return result

b = extract(data)
a = extract(after)
print('BASELINE:')
for p in sorted(b): 
    for pkg in sorted(b[p]): print(f'  {p} | {pkg} = {b[p][pkg]}')
print()
print('AFTER:')
for p in sorted(a):
    for pkg in sorted(a[p]): print(f'  {p} | {pkg} = {a[p][pkg]}')
"

